def get_transaction_absence_proof(
    self, height: object, tx_id: object, params: dict | None = None
) -> tuple[int, dict]:
    """GET /v1/blocks/{height}/absence-proof/{tx_id} — a non-inclusion
    proof for a transaction in one confirmed canonical block.

    The endpoint takes no query parameters: any parameter is
    400 ``{"error": "input"}``. The height must be a non-negative ASCII
    decimal without leading zeros and the tx_id 64 lowercase hex
    characters; a malformed or unknown height is
    404 ``{"error": "block_not_found"}``, a malformed tx_id is
    404 ``{"error": "transaction_not_found"}``, a pending block is
    409 ``{"error": "block_pending"}`` and a transaction already present
    in the block is 409 ``{"error": "transaction_present"}``.

    On success the body has the fixed key order ``height, tx_id,
    transaction_count, merkle_root, block_hash, lower, upper``:
    ``lower`` / ``upper`` are the inclusion proofs (``tx_id, index,
    siblings``) of the block's transactions immediately before / after
    the target in the block's ascending tx_id leaf order, or ``null`` on
    the missing side; an empty block has both sides null and the fixed
    empty Merkle root. Everything is computed from the canonical block
    snapshot under the store lock — the pending mempool and candidate
    forks never contribute — and the read is pure.
    """
    if params:
        return 400, {"error": "input"}
    height_int = _parse_height_decimal(height)
    if height_int is None:
        return 404, {"error": "block_not_found"}
    if not crypto.is_hex64(tx_id):
        return 404, {"error": "transaction_not_found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block_not_found"}
        if block.status != STATUS_CONFIRMED:
            return 409, {"error": "block_pending"}
        tx_ids = [tx.tx_id for tx in block.transactions]
        position = bisect_left(tx_ids, tx_id)
        if position < len(tx_ids) and tx_ids[position] == tx_id:
            return 409, {"error": "transaction_present"}

        def neighbor(index: int | None) -> dict | None:
            if index is None:
                return None
            return {
                "tx_id": tx_ids[index],
                "index": index,
                "siblings": crypto.merkle_proof(tx_ids, index),
            }

        lower_index = position - 1 if position > 0 else None
        upper_index = position if position < len(tx_ids) else None
        return 200, {
            "height": block.height,
            "tx_id": tx_id,
            "transaction_count": len(tx_ids),
            "merkle_root": block.merkle_root,
            "block_hash": block.block_hash,
            "lower": neighbor(lower_index),
            "upper": neighbor(upper_index),
        }

# -- accounts -----------------------------------------------------------

def get_account(self, account: str) -> tuple[int, dict]:
    with self.store.lock:
        entry = self.store.accounts.get(account)
        if entry is None:
            return 404, {"error": "account not found"}
        return 200, {
            "account": account,
            "balance": self.reported_balance(account),
            "confirmed_transactions": list(entry["transactions"]),
        }

# -- account state Merkle tree -------------------------------------------

def _state_tree(
    self, chain: list | None = None
) -> tuple[list[tuple[str, int, list[str]]], list[str], str]:
    """Build the confirmed account rows (ascending account), their leaves
    and the Merkle root, all from the confirmed chain under the current
    endowment. ``chain`` defaults to the whole canonical chain; a confirmed
    prefix replays historical state deterministically. Caller must hold the
    store lock.
    """
    if chain is None:
        chain = self.store.chain
    rows = self.store.account_state_rows(chain, self.initial_balance)
    leaves = [
        crypto.account_state_leaf(account, balance, transactions)
        for account, balance, transactions in rows
    ]
    return rows, leaves, crypto.account_state_root(leaves)

def get_state_root(self, height: object = None) -> tuple[int, dict]:
    """GET /v1/state/root and GET /v1/state/root/{height}.

    Without a height the tree is anchored to the highest block. A pending
    chain tip anchors nothing yet, so the endpoint returns 404 until the
    tip is confirmed.

    With a path height the state is replayed only from genesis through
    that block: the height must be an unsigned ASCII decimal without
    leading zeros (the empty string, signs, whitespace, decimal/scientific
    forms and non-ASCII digits are treated like any unknown path), the
    block must exist on the canonical chain and be confirmed — an unknown,
    non-canonical or pending height returns 404. The success body has
    exactly the same four fields as the unanchored endpoint.
    """
    with self.store.lock:
        if height is None:
            anchor = self.store.tip()
        else:
            # Strict ASCII unsigned decimal with no leading zeros, signs
            # or whitespace; every malformed value is an unknown path
            # (404).
            height_int = _parse_height_decimal(height)
            if height_int is None:
                return 404, {"error": "block not found"}
            anchor = self.store.block_at(height_int)
            if anchor is None:
                return 404, {"error": "block not found"}
        if anchor.status != STATUS_CONFIRMED:
            return 404, {"error": "chain tip is pending confirmation"}
        prefix = self.store.chain if height is None else self.store.chain[: anchor.height + 1]
        rows, _leaves, root = self._state_tree(prefix)
        return 200, {
            "state_root": root,
            "height": anchor.height,
            "block_hash": anchor.block_hash,
            "account_count": len(rows),
        }

def get_account_proof(
    self, account: str, params: dict | None = None
) -> tuple[int, dict]:
    """GET /v1/accounts/{account}/proof — an inclusion proof in the
    account-state tree.

    Without ``height`` the proof is anchored to the highest (confirmed)
    block. With ``height=H`` the state is deterministically replayed from
    the canonical confirmed prefix through that block only: the value must
    be a plain non-negative ASCII decimal string without leading zeros
    (no signs, whitespace, decimal/scientific forms or non-ASCII digits;
    a malformed or repeated query parameter is 400), and an
    unknown/non-canonical/pending
    anchor height is 404. ``height`` is the only accepted query parameter;
    any unknown parameter is 400. Returns 404 while a pending tip anchors
    the default view, or for an account absent from the (historical)
    confirmed account set.
    """
    height_raw: object = None
    if params is not None:
        if any(key != "height" for key in params):
            return 400, {"error": "unknown query parameter"}
        height_raw = params.get("height")
    anchor_height: int | None = None
    if height_raw is not None:
        anchor_height = _parse_height_decimal(height_raw)
        if anchor_height is None:
            return 400, {"error": "height must be a non-negative decimal"}
    with self.store.lock:
        if anchor_height is None:
            anchor = self.store.tip()
        else:
            anchor = self.store.block_at(anchor_height)
            if anchor is None:
                return 404, {"error": "anchor block not found"}
        if anchor.status != STATUS_CONFIRMED:
            return 404, {"error": "chain tip is pending confirmation"}
        prefix = (
            self.store.chain
            if anchor_height is None
            else self.store.chain[: anchor.height + 1]
        )
        rows, leaves, root = self._state_tree(prefix)
        index = next(
            (i for i, (name, _b, _t) in enumerate(rows) if name == account),
            None,
        )
        if index is None:
            return 404, {"error": "account not found"}
        account_name, balance, transactions = rows[index]
        siblings = crypto.merkle_proof(leaves, index)
        return 200, {
            "account": account_name,
            "balance": balance,
            "confirmed_transactions": transactions,
            "index": index,
            "state_root": root,
            "height": anchor.height,
            "block_hash": anchor.block_hash,
            "siblings": siblings,
        }

